    text = re.sub(r"-+", "-", text).strip("-")
    return text or fallback


def run(cmd: list[str], cwd: Path | None = None) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        cmd,
        cwd=str(cwd) if cwd else None,
        text=True,
        capture_output=True,
        check=False,
    )


def clean_string(value: Any) -> str:
    return str(value or "").strip()


def looks_like_session_key(value: str) -> bool:
    return bool(value and value != "current" and value.startswith("agent:") and value.count(":") >= 2)


def session_agent_id(session_key: str) -> str:
    parts = session_key.split(":")
    return parts[1] if len(parts) > 1 and parts[0] == "agent" else ""


def session_chat_type(session_key: str) -> str:
    parts = session_key.split(":")
    return parts[3] if len(parts) > 3 and parts[0] == "agent" else ""


def session_peer_id(session_key: str) -> str:
    parts = session_key.split(":")
    return ":".join(parts[4:]) if len(parts) > 4 and parts[0] == "agent" else ""


def runtime_session_key(env: dict[str, str] | None = None) -> str | None:
    source = env if env is not None else os.environ
    for name in SESSION_KEY_ENV_VARS:
        value = clean_string(source.get(name))
        if looks_like_session_key(value):
            return value
    return None


def read_config_agents(workspace: Path) -> list[dict[str, Any]]:
    config_path = workspace / "openclaw.json"
    try:
        data = json.loads(config_path.read_text(encoding="utf-8"))
    except Exception:
        return []
    agents = data.get("agents", {})
    if isinstance(agents, dict) and isinstance(agents.get("list"), list):
        return [agent for agent in agents["list"] if isinstance(agent, dict)]
    return []


def infer_workspace_agent_ids(workspace: Path, cwd: Path) -> set[str]:
    try:
        resolved_cwd = cwd.expanduser().resolve()
    except Exception:
        return set()

    ids: set[str] = set()
    for agent in read_config_agents(workspace):
        agent_id = clean_string(agent.get("id"))
        agent_workspace = clean_string(agent.get("workspace"))
        if not agent_id or not agent_workspace:
            continue
        try:
            resolved_workspace = Path(agent_workspace).expanduser().resolve()
        except Exception:
            continue
        if resolved_cwd == resolved_workspace or resolved_workspace in resolved_cwd.parents:
            ids.add(agent_id)
    return ids


def load_sessions(cmd: list[str], cwd: Path | None = None) -> list[dict[str, Any]]:
    res = run(cmd, cwd=cwd)
    if res.returncode != 0:
        return []
    try:
        sessions = json.loads(res.stdout).get("sessions") or []
    except Exception:
        return []
    return [session for session in sessions if isinstance(session, dict)]


def session_matches(
    session: dict[str, Any],
    *,
    agent_ids: set[str] | None = None,
    chat_type: str | None = None,
    peer_id: str | None = None,
) -> bool:
    key = clean_string(session.get("key"))
    if not looks_like_session_key(key):
        return False

    normalized_agent_ids = {clean_string(agent_id) for agent_id in (agent_ids or set()) if clean_string(agent_id)}
    if normalized_agent_ids:
        agent = clean_string(session.get("agentId")) or session_agent_id(key)
        if agent not in normalized_agent_ids:
            return False

    normalized_chat_type = clean_string(chat_type)
    if normalized_chat_type:
        kind = clean_string(session.get("kind")) or clean_string(session.get("chatType")) or session_chat_type(key)
        if kind != normalized_chat_type:
            return False

    normalized_peer_id = clean_string(peer_id)
    if normalized_peer_id and normalized_peer_id not in key and session_peer_id(key) != normalized_peer_id:
        return False

    return True


def newest_session_key(sessions: list[dict[str, Any]]) -> str | None:
    if not sessions:
        return None
    sessions = sorted(sessions, key=lambda session: int(session.get("updatedAt") or 0), reverse=True)
    return clean_string(sessions[0].get("key")) or None


def resolve_current_session_key(
    *,
    workspace: Path | None = None,
    cwd: Path | None = None,
    env: dict[str, str] | None = None,
    agent_id: str | None = None,
    chat_type: str | None = None,
    peer_id: str | None = None,
) -> str | None:
    """Resolve the current OpenClaw session with channel/agent context when available."""
    workspace = (workspace or Path(os.getcwd())).expanduser().resolve()
    cwd = (cwd or Path(os.getcwd())).expanduser().resolve()
    explicit_agent_ids = {clean_string(agent_id)} if clean_string(agent_id) else set()
    has_explicit_filters = bool(explicit_agent_ids or clean_string(chat_type) or clean_string(peer_id))
    env_key = runtime_session_key(env)
    if env_key and (
        not has_explicit_filters
        or session_matches(
            {"key": env_key, "agentId": session_agent_id(env_key), "kind": session_chat_type(env_key)},
            agent_ids=explicit_agent_ids,
            chat_type=chat_type,
            peer_id=peer_id,
        )
    ):
        return env_key

    agent_ids = set(explicit_agent_ids)
    env_source = env if env is not None else os.environ
    env_agent_id = clean_string(env_source.get("OPENCLAW_MCP_AGENT_ID"))
    if env_agent_id and not agent_ids:
        agent_ids.add(env_agent_id)
    if not agent_ids:
        agent_ids = infer_workspace_agent_ids(workspace, cwd)

    for active_minutes in ("180", None):
        cmd = ["openclaw", "sessions", "--all-agents", "--limit", "50", "--json"]
        if active_minutes:
            cmd[2:2] = ["--active", active_minutes]
        sessions = load_sessions(cmd, cwd=workspace)
        filtered = [
            session
            for session in sessions
            if session_matches(session, agent_ids=agent_ids, chat_type=chat_type, peer_id=peer_id)
        ]
        if filtered:
            return newest_session_key(filtered)
        if not agent_ids and not chat_type and not peer_id and sessions:
            return newest_session_key([session for session in sessions if session_matches(session)])

    for cmd in (
        ["openclaw", "sessions", "--active", "180", "--limit", "10", "--json"],
        ["openclaw", "sessions", "--limit", "10", "--json"],
    ):
        sessions = load_sessions(cmd, cwd=workspace)
        filtered = [
            session
            for session in sessions
            if session_matches(session, agent_ids=agent_ids, chat_type=chat_type, peer_id=peer_id)
        ]
        if filtered:
            return newest_session_key(filtered)
        if not agent_ids and not chat_type and not peer_id and sessions:
            return newest_session_key([session for session in sessions if session_matches(session)])
    return None


def format_timestamp(value: str | None) -> str:
    if not value:
        return "unknown-time"
    try:
        parsed = dt.datetime.fromisoformat(value.replace("Z", "+00:00"))
        return parsed.astimezone(dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3] + "Z"
    except Exception:
        return value


def text_from_content_parts(parts: Any) -> tuple[str, list[str]]:
    if isinstance(parts, str):
        return parts, []
    if not isinstance(parts, list):
        return str(parts) if parts else "", []

    text_chunks: list[str] = []
    attachments: list[str] = []
    for part in parts:
        if isinstance(part, str):
            text_chunks.append(part)
            continue
        if not isinstance(part, dict):
            continue
        ptype = part.get("type")
        if ptype == "text":
            text_chunks.append(str(part.get("text", "")))
        elif ptype in {"image", "input_image"}:
            source = part.get("source") or part.get("image") or {}
            if isinstance(source, dict):
                label = source.get("path") or source.get("media_id") or source.get("url") or "inline-image"
            else:
                label = source or "inline-image"
            attachments.append(f"[Image: {label}]")
        elif ptype == "toolCall":
            continue
    return "".join(text_chunks), attachments


def tool_result_text(data: dict[str, Any]) -> str:
    if "result" in data:
        return str(data.get("result", ""))
    message = data.get("message", {})
    content = message.get("content", data.get("content", ""))
    text, attachments = text_from_content_parts(content)
    if attachments:
        return "\n".join(attachments + ([text] if text else []))
    return text


def parse_events_to_messages(events_path: Path) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    messages: list[dict[str, Any]] = []
    stats: dict[str, Any] = {
        "events": 0,
        "user": 0,
        "assistant": 0,
        "tool_calls": 0,
        "tool_results": 0,
        "tool_errors": 0,
        "tools": Counter(),
        "model": None,
        "provider": None,
    }

    if not events_path.exists():
        return messages, stats

    with events_path.open("r", encoding="utf-8") as f:
        for line in f:
            if not line.strip():
                continue
            try:
                event = json.loads(line)
            except json.JSONDecodeError:
                continue

            stats["events"] += 1
            etype = event.get("type")
            ts = event.get("ts") or event.get("timestamp")
            data = event.get("data", {}) or {}
            stats["model"] = stats["model"] or event.get("modelId")
            stats["provider"] = stats["provider"] or event.get("provider")

            if etype == "user.message":
                message = data.get("message", {})
                text, attachments = text_from_content_parts(message.get("content", []))
                messages.append({
                    "role": "user",
                    "timestamp": ts,
                    "content": text.strip(),
                    "attachments": attachments,
                })
                stats["user"] += 1

            elif etype == "assistant.message":
                message = data.get("message", {})
                text, _ = text_from_content_parts(message.get("content", []))
                if text.strip():
                    messages.append({
                        "role": "assistant",
                        "timestamp": ts,
                        "content": text.strip(),
                    })
                    stats["assistant"] += 1

            elif etype == "tool.call":
                name = data.get("name") or data.get("toolName") or "unknown"
                messages.append({
                    "role": "tool_call",
                    "timestamp": ts,
                    "tool": name,
                    "input": data.get("arguments", data.get("input", {})),
                })
                stats["tool_calls"] += 1
                stats["tools"][name] += 1

            elif etype == "tool.result":
                message = data.get("message", {})
                name = data.get("name") or data.get("toolName") or message.get("toolName") or "unknown"
                error = data.get("error") or message.get("error")
                output = tool_result_text(data)
                messages.append({
                    "role": "tool_result",
                    "timestamp": ts,
                    "tool": name,
                    "output": output,
                    "error": error,
                })
                stats["tool_results"] += 1
                if error or re.search(r"\b(error|failed|timeout|timed out|exception)\b", output, re.I):
                    stats["tool_errors"] += 1

    return messages, stats


def strip_ansi(text: str) -> str:
    return ANSI_RE.sub("", text)


def format_json_block(value: Any) -> str:
    try:
        return json.dumps(value, ensure_ascii=False, indent=2)
    except Exception:
        return str(value)


def format_text_block(text: str) -> str:
    text = text or ""
    text = strip_ansi(text)
    return text.rstrip() or "(empty)"


def format_messages(messages: list[dict[str, Any]], agent_name: str) -> str:
    chunks: list[str] = []
    for msg in messages:
        role = msg.get("role")
        ts = format_timestamp(msg.get("timestamp"))
        if role == "user":
            header = f"## You ({ts})"
            body_parts = []
            attachments = msg.get("attachments") or []
            if attachments:
                body_parts.extend(attachments)
            if msg.get("content"):
                body_parts.append(msg["content"])
            body = "\n\n".join(part for part in body_parts if part)
            chunks.append(f"{header}\n\n{body or '(empty)'}")
        elif role == "assistant":
            header = f"## {agent_name} ({ts})"
            body = msg.get("content") or "(empty)"
            chunks.append(f"{header}\n\n{body}")
        elif role == "tool_call":
            header = f"## {agent_name} ({ts})"
            tool = msg.get("tool", "unknown")
            body = (
                f"🔧 **Tool Call**: `{tool}` ({tool})\n"
                f"**Input**:\n"
                f"```json\n{format_json_block(msg.get('input'))}\n```"
            )
            chunks.append(f"{header}\n\n{body}")
        elif role == "tool_result":
            header = f"## Tool ({ts})"
            tool = msg.get("tool", "unknown")
            output = format_text_block(msg.get("output", ""))
            extra = ""
            if msg.get("error"):
                extra = f"\n**Error**: `{msg['error']}`\n"
            body = (
                f"📦 **Tool Output**: `{tool}` ({tool}){extra}\n"
                f"**Output**:\n"
                f"```text\n{output}\n```"
            )
            chunks.append(f"{header}\n\n{body}")
    return "\n\n".join(chunks)


def ai_analysis_section(issue: str, session_key: str, stats: dict[str, Any]) -> str:
    tool_summary = ", ".join(
        f"{name}×{count}" for name, count in stats.get("tools", Counter()).most_common(8)
    ) or "无"

    findings: list[str] = []
    if stats.get("tool_errors"):
        findings.append("- 工具或上游服务存在错误 / 超时，需要优先查看 Tool Output 和 Backend Logs 中的 error/timeout 行。")
    else:
        findings.append("- 未观察到明显工具报错，可优先结合上下文确认是否是结果质量、权限或目标定位问题。")

    if stats.get("tool_calls", 0) > 20:
        findings.append("- 本次会话工具调用较多，建议重点关注失败前后的连续工具链，通常根因就在最后 3-5 次调用内。")
    if stats.get("provider") or stats.get("model"):
        findings.append(
            f"- 运行模型信息：provider={stats.get('provider') or 'unknown'}；model={stats.get('model') or 'unknown'}。"
        )

    return f"""## AI Analysis

### 定位摘要

- **问题标题**：{issue}
- **Session Key**：`{session_key}`
- **事件数**：{stats.get('events', 0)}；用户消息 {stats.get('user', 0)}；AI 消息 {stats.get('assistant', 0)}；工具调用 {stats.get('tool_calls', 0)}；工具结果 {stats.get('tool_results', 0)}；疑似工具错误 {stats.get('tool_errors', 0)}
- **高频工具**：{tool_summary}

### 初步判断

{chr(10).join(findings)}
"""


def export_trajectory(workspace: Path, session_key: str, output_root: Path) -> Path:
    export_dir = output_root / f"trajectory-{slugify(session_key)}-{dt.datetime.now().strftime('%Y%m%d-%H%M%S')}"
    export_dir.mkdir(parents=True, exist_ok=True)
    cmd = [
        "openclaw",
        "sessions",
        "export-trajectory",
        "--session-key",
        session_key,
        "--workspace",
        str(workspace),
        "--output-dir",
        str(export_dir),
    ]
    res = run(cmd, cwd=workspace)
    if res.returncode != 0:
        raise RuntimeError(f"export-trajectory failed: {res.stderr or res.stdout}")
    return export_dir


def capture_backend_logs(workspace: Path, limit_lines: int, max_bytes: int) -> str:
    cmd = ["openclaw", "logs", "--limit", str(limit_lines)]
    res = run(cmd, cwd=workspace)
    text = res.stdout or res.stderr or ""
    text = strip_ansi(text)
    if len(text.encode("utf-8")) > max_bytes:
        encoded = text.encode("utf-8")[:max_bytes]
        text = encoded.decode("utf-8", errors="ignore") + "\n...[truncated]"
    return text.strip() or "(no backend logs captured)"


def build_report(
    *,
    workspace: Path,
    issue: str,
    agent_name: str,
    session_key: str,
    export_dir: Path,
    include_logs: bool,
    log_lines: int,
    max_bytes: int,
) -> tuple[Path, str]:
    events_path = export_dir / "events.jsonl"
    messages, stats = parse_events_to_messages(events_path)
    logs = capture_backend_logs(workspace, log_lines, max_bytes) if include_logs else "(skipped with --no-logs)"

    generated_ts = dt.datetime.now().strftime("%Y%m%d-%H%M%S")
    report_dir = default_report_dir()
    report_dir.mkdir(parents=True, exist_ok=True)
    report_path = report_dir / build_report_filename(generated_ts, session_key, issue)

    metadata = f"""## Export Metadata

- Issue: `{issue}`
- Session: `{session_key}`
- Raw trajectory bundle: `{export_dir}`
- Workspace: `{workspace}`
"""

    transcript = format_messages(messages, agent_name)
    backend_logs_section = f"## Backend Logs\n\n```log\n{logs}\n```"

    report = f"# Chat with {agent_name}\n\n{ai_analysis_section(issue, session_key, stats)}\n{metadata}\n\n{transcript}\n\n{backend_logs_section}\n"
    report_path.write_text(report, encoding="utf-8")
    return report_path, report


def main() -> int:
    parser = argparse.ArgumentParser(description="Export OpenClaw chat report")
    parser.add_argument("--workspace", default=os.getcwd())
    parser.add_argument("--session-key", default="current")
    parser.add_argument("--agent")
    parser.add_argument("--agent-id")
    parser.add_argument("--chat-type")
    parser.add_argument("--peer-id")
    parser.add_argument("--issue", required=True)
    parser.add_argument("--agent-name", default="小爪")
    parser.add_argument("--output-dir", default=str(default_report_dir()))
    parser.add_argument("--log-lines", type=int, default=300)
    parser.add_argument("--max-bytes", type=int, default=400000)
    parser.add_argument("--no-logs", action="store_true")
    args = parser.parse_args()

    workspace = Path(args.workspace).expanduser().resolve()
    session_key = clean_string(args.session_key)
    agent_id = clean_string(args.agent_id or args.agent)
    chat_type = clean_string(args.chat_type)
    peer_id = clean_string(args.peer_id)

    if session_key == "current":
        session_key = resolve_current_session_key(
            workspace=workspace,
            cwd=Path.cwd(),
            agent_id=agent_id or None,
            chat_type=chat_type or None,
            peer_id=peer_id or None,
        ) or ""
    if not looks_like_session_key(session_key):
        raise RuntimeError("Failed to auto-resolve current session key.")

    trajectory_root = workspace / "trajectory-exports"
    trajectory_root.mkdir(parents=True, exist_ok=True)
    export_dir = export_trajectory(workspace, session_key, trajectory_root)
    report_path, _ = build_report(
        workspace=workspace,
        issue=args.issue,
        agent_name=args.agent_name,
        session_key=session_key,
        export_dir=export_dir,
        include_logs=not args.no_logs,
        log_lines=args.log_lines,
        max_bytes=args.max_bytes,
    )
    print(str(report_path))
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(str(exc), file=sys.stderr)
        raise

